import {BASE_PROPERTIES,BASE_FEATURES,FORMS,BASIS,ELEMENTS,formLabel,basisLabel,freshWorkspace,validateWorkspace,exactNumber,parseComposition,compositionKey,validateComposition,suggestMapping,buildDataset,predictProperty,trainingRows,uid} from './prediction-model.js';
import {trainingControls,modelReport} from './prediction-report.js';
import {readPredictionFile,toCSV} from './prediction-import.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>Number.isFinite(n)?Number(n.toPrecision(5)).toLocaleString('zh-CN',{maximumSignificantDigits:5}):'—';
const date=n=>new Date(n).toLocaleString();
const unitLabel=p=>p.name+(p.unit?' · '+p.unit:'');
const option=(value,label,selected)=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`;
const propertyOptions=(items,value)=>items.map(p=>option(p.id,unitLabel(p),value)).join('');
export function createPredictionController({host,load,persist,saveText,toast,isReady,onCount}) {
 const listeners=new AbortController();
 let workspace=freshWorkspace(),loaded=false,loading=null,libraryKey='',panel='predict',busy=false,error='',worker=null,generation=0;
 let file=null,sheet=0,headerRow=1,mapping=[],preview=null,results=[],previewOptions=null,importSettings={basis:'at',form:'',verified:false};
 let form='powder',basis='at',formula='',conditions={},draftName='',trainStatus='',lastResultInput=null;
 let queue=Promise.resolve(),engine=null,reportId=null;
 const ml=globalThis.materiaDesktop;
 let trainingSettings={algorithms:['extra_trees','random_forest','hist_gradient_boosting','ridge','elastic_net','svr'],trees:256,threads:4,seed:8427,search:'standard'};
 const engineReady=ml?.mlStatus?ml.mlStatus().then(value=>{engine=value;render();}).catch(e=>{engine={error:e.message};render();}):Promise.resolve().then(()=>{engine={error:'完整机器学习引擎需要桌面版。网页可查看和管理已有数据。'};});
 function captureTraining(){const f=host.querySelector('#prediction-train-form');if(f){const d=new FormData(f);trainingSettings={algorithms:d.getAll('algorithm'),trees:Number(d.get('trees')),threads:Number(d.get('threads')),seed:Number(d.get('seed')),search:d.get('search')};}}

 const currentRows=()=>workspace.datasets.reduce((n,d)=>n+d.rows.length,0);
 const materialForms=()=>{const values=new Map(Object.entries(FORMS));for(const row of [...workspace.datasets,...workspace.models])if(row.form&&!values.has(row.form))values.set(row.form,row.form);return [...values];};
 const formOptions=selected=>materialForms().map(([value,label])=>option(value,label,selected)).join('');
 const basisOptions=selected=>Object.entries(BASIS).map(([value,label])=>option(value,label,selected)).join('');
 function status(){onCount?.(`${workspace.datasets.length} 个数据集 · ${currentRows()} 条记录`);}
 async function save(next){const token=generation,expectedKey=libraryKey;busy=true;error='';
  const operation=queue.then(()=>persist({libraryKey:expectedKey,state:next}));queue=operation.catch(()=>{});
  try{await operation;if(token!==generation)return;workspace=next;}catch(e){if(token===generation)error='未保存：'+e.message;throw e;}finally{if(token===generation)busy=false;}
 }
 async function ensureLoaded(){if(loaded)return;if(loading)return loading;const token=generation;
  loading=(async()=>{try{const value=await load();if(token!==generation)return;workspace=value.state?validateWorkspace(value.state):freshWorkspace();libraryKey=value.libraryKey;loaded=true;error='';}
   catch(e){if(token===generation)error=e.message;}finally{if(token===generation){loading=null;render();}}})();return loading;
 }
 function capture(){const f=host.querySelector('#prediction-form');if(f){formula=f.elements.formula.value;form=f.elements.form.value;basis=f.elements.basis.value;conditions={};for(const spec of workspace.features){const el=f.elements['feature:'+spec.id];if(el&&el.value.trim())conditions[spec.id]=spec.type==='number'?exactNumber(el.value):el.value.trim();}}}
 function shell(content){host.innerHTML=`<div class="prediction-heading"><div><span class="prediction-kicker">MATERIALS MACHINE LEARNING</span><h2>材料性能预测</h2><p>用本地实验或计算数据训练通用数值回归模型。</p></div><span class="prediction-local">本机计算 · 数据保存在当前文献库</span></div><nav class="prediction-tabs" aria-label="预测工具"><button data-prediction-panel="predict" aria-pressed="${panel==='predict'}">材料预测</button><button data-prediction-panel="datasets" aria-pressed="${panel==='datasets'}">数据集 <small>${workspace.datasets.length}</small></button><button data-prediction-panel="models" aria-pressed="${panel==='models'}">模型训练</button><button data-prediction-panel="properties" aria-pressed="${panel==='properties'}">目标与描述符</button></nav><div class="prediction-feedback" role="status" ${error?'':'hidden'}>${esc(error)}</div>${content}`;status();}
 function render(){if(host.hidden)return;captureTraining();const importForm=host.querySelector('#prediction-import-form');if(importForm){draftName=importForm.elements.name.value;importSettings={basis:importForm.elements.basis.value,form:importForm.elements.form.value,verified:importForm.elements.verified.checked};}if(!loaded){shell(`<div class="prediction-empty"><h3>${error?'预测工作区未打开':'正在打开预测工作区…'}</h3>${error?'<button class="outline-button" data-prediction-action="retry">重新读取</button>':''}</div>`);return;}
  if(panel==='predict')shell(predictHTML());if(panel==='datasets')shell(datasetsHTML());if(panel==='models')shell(modelsHTML());if(panel==='properties')shell(propertiesHTML());
 }
 function scopeFields(){return`<label>材料类型<select name="form">${formOptions(form)}</select></label><label>成分表达<select name="basis">${basisOptions(basis)}</select></label>`;}
 function activeModels(){return workspace.models.filter(m=>m.active&&m.form===form&&m.basis===basis);}
 function predictHTML(){const models=activeModels();const usedFeatures=new Set(models.flatMap(m=>m.encoder.specs.map(f=>f.id)));
  return`<div class="prediction-two-col"><form id="prediction-form" class="prediction-card"><div class="prediction-card-title"><h3>输入材料</h3><span>${basis==='formula'?'化学计量式自动归一化':'元素合计 100%'}</span></div><div class="prediction-grid">${scopeFields()}</div><label>成分式<input name="formula" value="${esc(formula)}" placeholder="${basis==='formula'?'例如 LiFePO4':'例如 Fe80Si9B11'}" autocomplete="off" required></label><p class="prediction-help">百分比模式要求元素合计 100%；化学计量式模式支持 LiFePO4、Al2O3 等常规式并自动转为原子分数。</p><details class="prediction-elements"><summary>按元素填写百分比</summary><div id="prediction-element-rows">${elementRows(formula)}</div><button type="button" class="text-button" data-prediction-action="add-element">＋ 添加元素</button><button type="button" class="outline-button" data-prediction-action="apply-elements">应用到成分式</button></details><details ${usedFeatures.size?'open':''}><summary>结构、工艺与测试描述符${usedFeatures.size?' · 模型使用 '+usedFeatures.size+' 项':''}</summary><div class="prediction-grid prediction-conditions">${workspace.features.filter(f=>usedFeatures.has(f.id)).map(f=>`<label>${esc(unitLabel(f))}<input name="feature:${esc(f.id)}" value="${esc(conditions[f.id]??'')}" ${f.type==='number'?'type="number" step="any"':''} placeholder="按预测条件填写"></label>`).join('')||'<p class="prediction-help">训练模型后，会在这里显示该模型使用的描述符。</p>'}</div></details><button class="primary" type="submit" ${!models.length||busy?'disabled':''}>预测性能</button>${!models.length?'<p class="prediction-help">当前材料类型和成分表达方式还没有通过验证的模型。</p><button type="button" class="text-button" data-prediction-panel="datasets">导入数据 →</button>':''}</form><div class="prediction-card prediction-output"><div class="prediction-card-title"><h3>性能结果</h3><label class="text-button prediction-file-label">批量预测 CSV<input id="prediction-batch" type="file" accept=".csv,.tsv" hidden ${busy||!models.length?'disabled':''}></label><button class="text-button" data-prediction-action="export-results" ${results.length?'':'disabled'}>导出结果</button></div>${results.length?`<p class="prediction-help">${esc(lastResultInput?.formula)} · ${esc(formLabel(lastResultInput?.form))} · ${esc(basisLabel(lastResultInput?.basis))}</p>`:'<p class="prediction-help">预测值、交叉验证误差和适用域提示会逐项显示。</p>'}<div class="prediction-result-list">${predictionResults(models)}</div><p class="prediction-help">“90% 历史绝对误差范围”来自折外残差分位数，是经验误差带，不是统计置信区间或实验确认。</p></div></div>`;
 }
 function propertyResult(p,models){const r=results.find(r=>r.target===p.id),m=models.find(m=>m.target===p.id),range=r?.interval?.map(number).join(' ～ ');return`<div class="prediction-result"><div><strong>${esc(p.name)}</strong><small>${esc(p.unit||'无量纲')}</small></div><div>${r?.value!==undefined?`<b>${number(r.value)}</b><small>${r.derived?'由 Tx − Tg 计算':range?'90% 历史绝对误差范围 '+range:'分组验证 MAE '+number(r.mae)}${r.stale?' · 数据已变更':''}</small>${r.warnings?.length?`<small class="prediction-warning">${esc(r.warnings.join('；'))}</small>`:''}`:`<span class="prediction-muted">${esc(r?.error||(m?'等待输入':'待训练'))}</span>`}</div></div>`;}
 function predictionResults(models){
  const available=new Set([...models.map(m=>m.target),...results.map(r=>r.target)]);
  const ready=workspace.properties.filter(p=>available.has(p.id)),pending=workspace.properties.filter(p=>!available.has(p.id));
  return (ready.map(p=>propertyResult(p,models)).join('')||'<div class="prediction-output-empty">导入实验数据并训练模型后，<br>在这里查看可预测的性能。</div>')+(pending.length?`<details class="prediction-pending"><summary>待训练的性能 · ${pending.length}</summary>${pending.map(p=>propertyResult(p,models)).join('')}</details>`:'');
 }
 function elementRows(value){let c;try{c=parseComposition(value);}catch{c={Fe:'',Si:'',B:''};}return Object.entries(c).map(([e,n])=>elementRow(e,n)).join('');}
 function elementRow(e='',n=''){return`<div class="prediction-element"><select aria-label="元素">${option('','选择元素',e)}${ELEMENTS.map(v=>option(v,v,e)).join('')}</select><input aria-label="元素百分比" type="number" min="0" max="100" step="any" value="${esc(n)}" placeholder="百分比"><span>%</span><button type="button" class="text-button" data-prediction-action="remove-element" aria-label="移除此元素">×</button></div>`;}
 function datasetsHTML(){return`<div class="prediction-actions"><label class="outline-button prediction-file-label">导入 Excel / CSV<input id="prediction-upload" type="file" accept=".xlsx,.csv,.tsv" hidden ${busy?'disabled':''}></label><button class="outline-button" data-prediction-action="template">下载数据模板</button><button class="text-button" data-prediction-action="export-workspace">导出预测工作区</button><label class="text-button prediction-file-label">恢复工作区<input id="prediction-restore" type="file" accept=".json" hidden ${busy?'disabled':''}></label></div>${file?importHTML():''}<div class="prediction-card"><h3>材料数据集</h3>${workspace.datasets.length?`<div class="prediction-table-wrap"><table><thead><tr><th>数据集</th><th>材料类型／成分表达</th><th>有效记录</th><th>覆盖性能</th><th>操作</th></tr></thead><tbody>${workspace.datasets.map(d=>`<tr><td><strong>${esc(d.name)}</strong><small>${esc(d.filename)}${d.sheetName?' · '+esc(d.sheetName):''}</small></td><td>${esc(formLabel(d.form))}<small>${esc(basisLabel(d.basis))}</small></td><td>${d.rows.length}<small>${d.issues.length} 行跳过 · ${d.duplicates} 行重复</small></td><td>${workspace.properties.filter(p=>d.rows.some(r=>r.targets[p.id]!==undefined)).map(p=>esc(p.name)).join('、')}</td><td><button class="text-button" data-export-dataset="${esc(d.id)}">导出</button><button class="text-button" data-remove-dataset="${esc(d.id)}" ${busy?'disabled':''}>移除…</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="prediction-empty"><h3>从第一份材料数据开始</h3><p>导入实验或计算数据，再核对成分、单位、材料类型、描述符和预测目标。</p><p>不等式、区间、未确定元素会保留在导入报告中，不直接充当确定数值标签。</p></div>'}<p class="prediction-help">数据集导入后不会自动改动已训练模型。新增数据后请重新训练。预测结果不会作为真实标签回流。</p></div>`;}
 function importHTML(){const current=file.sheets[sheet],headers=current.rows[headerRow-1]||[],table=current.rows.slice(headerRow-1);return`<section class="prediction-card"><div class="prediction-card-title"><h3>核对导入 · ${esc(file.filename)}</h3><button class="text-button" data-prediction-action="close-import">收起</button></div><form id="prediction-import-form"><div class="prediction-grid"><label>数据集名称<input name="name" value="${esc(draftName)}" required></label><label>工作表<select id="prediction-sheet">${file.sheets.map((s,i)=>option(String(i),s.name,String(sheet))).join('')}</select></label><label>表头所在行<input id="prediction-header" type="number" min="1" max="${current.rows.length}" value="${headerRow}"></label><label>成分表达<select name="basis">${basisOptions(importSettings.basis)}</select></label><label>材料类型<input name="form" list="prediction-form-options" value="${esc(importSettings.form)}" maxlength="80" placeholder="选择或输入自定义类型" required><datalist id="prediction-form-options">${materialForms().map(([k,v])=>`<option value="${esc(k)}">${esc(v)}</option>`).join('')}</datalist></label></div><p class="prediction-help">不同材料类型和成分表达方式分别建模；可输入自定义材料类型。化学计量式模式支持 LiFePO4 等普通式，其他模式要求元素合计 100%。单位不会自动换算。</p>${current.formulaCount?`<p class="prediction-warning">文件含 ${current.formulaCount} 个公式，读取 Excel 已保存的结果，不执行公式。请先在 Excel 中重算并核对异常值。</p>`:''}<div class="prediction-table-wrap prediction-mapping"><table><thead><tr><th>原表列名／样例</th><th>用途</th><th>对应字段</th><th>字段单位</th></tr></thead><tbody>${headers.map((h,i)=>{const m=mapping[i]||{role:'ignore',id:''},items=m.role==='target'?workspace.properties:m.role==='feature'?workspace.features:[];return`<tr><td><strong>${esc(h||'未命名列 '+(i+1))}</strong><small>${esc(table.slice(1,4).map(r=>r[i]??'').join(' / ')).slice(0,160)}</small></td><td><select data-mapping-role="${i}">${[['ignore','忽略'],['composition','成分式'],['element','元素含量'],['feature','结构／工艺／测试描述符'],['target','数值预测目标'],['source','来源／DOI']].map(([k,v])=>option(k,v,m.role)).join('')}</select></td><td>${m.role==='element'?`<select data-mapping-id="${i}">${ELEMENTS.map(e=>option(e,e,m.id)).join('')}</select>`:items.length?`<select data-mapping-id="${i}">${propertyOptions(items,m.id)}</select>`:'—'}</td><td>${esc(items.find(p=>p.id===m.id)?.unit||'—')}</td></tr>`;}).join('')}</tbody></table></div><p class="prediction-help">没有对应字段？先到“目标与描述符”新增，再回来映射。尤其注意同名不同单位或测试定义必须拆成独立字段。</p><label class="prediction-check"><input type="checkbox" name="verified" ${importSettings.verified?'checked':''} required>已核对成分表达、材料类型、字段定义与单位，目标值来自实验或计算数据</label><button class="outline-button" type="submit" ${busy?'disabled':''}>预览可导入记录</button></form>${preview?`<div class="prediction-import-report"><strong>${preview.rows.length} 条可导入 · ${preview.issues.length} 行跳过 · ${preview.duplicates} 行重复</strong><p>${preview.qualified} 个非确定数值单元格未用作训练标签。</p>${preview.issues.length?`<details><summary>查看跳过原因</summary>${preview.issues.slice(0,40).map(i=>`<p>第 ${i.row+headerRow-1} 行：${esc(i.message)}</p>`).join('')}</details>`:''}<button class="primary" data-prediction-action="confirm-import" ${busy?'disabled':''}>确认导入数据集</button></div>`:''}</section>`;}
 function modelsHTML(){const datasets=workspace.datasets.filter(d=>d.form===form&&d.basis===basis);return`<div class="prediction-card"><h3>训练与分组验证</h3><p class="prediction-help">使用 scikit-learn 官方算法与 Pipeline。外层 5 折检验泛化误差，内层 3 折比较算法并调参；缺失值填补、分类编码、输入和目标标准化均在各训练折内拟合。同成分与所选来源不会跨折。</p><form id="prediction-train-form">${trainingControls(trainingSettings,engine)}<div class="prediction-grid">${scopeFields()}<label>验证方式<select name="validation"><option value="composition">按成分分组 · 5 折</option><option value="source">按来源与成分分组 · 5 折</option></select></label></div><fieldset><legend>训练数据集</legend>${datasets.map(d=>`<label class="prediction-check"><input name="dataset" type="checkbox" value="${esc(d.id)}" checked>${esc(d.name)} · ${d.rows.length} 条</label>`).join('')||'<p class="prediction-help">当前范围没有数据，请先导入相同材料类型和成分表达方式的记录。</p>'}</fieldset><fieldset><legend>数值预测目标</legend><div class="prediction-property-choices">${workspace.properties.map(p=>{const n=trainingRows(workspace,{datasetIds:datasets.map(d=>d.id),form,basis,target:p.id}).length;return`<label class="prediction-check"><input name="target" type="checkbox" value="${esc(p.id)}" ${n<15?'disabled':''}><span>${esc(p.name)}<small>${n} 条有效标签${n<15?' · 待补数据':''}</small></span></label>`;}).join('')}</div></fieldset><p class="prediction-help">至少 15 条有效标签和 5 组独立成分。模型必须优于训练折均值基线才会启用；折外残差用于给出经验误差带。</p><div class="prediction-actions"><button type="submit" class="primary" ${busy||!datasets.length||!engine?.ready?'disabled':''}>训练所选目标</button>${busy&&worker?'<button type="button" class="outline-button" data-prediction-action="cancel-train">停止训练</button>':''}<span id="prediction-train-status" role="status">${esc(trainStatus)}</span></div></form></div><div class="prediction-card"><div class="prediction-card-title"><h3>模型记录</h3><small>MAE／RMSE／P90 使用目标单位</small></div>${workspace.models.length?`<div class="prediction-table-wrap"><table><thead><tr><th>目标／范围</th><th>样本／分组</th><th>MAE</th><th>P90 绝对误差</th><th>R²</th><th>主要输入</th><th>状态</th><th></th></tr></thead><tbody>${[...workspace.models].reverse().map(m=>`<tr><td>${esc(unitLabel(m.property))}<small>${esc(m.estimator||'旧版自实现模型')}</small><small>${esc(formLabel(m.form))} · ${esc(basisLabel(m.basis))} · ${date(m.createdAt)}</small></td><td>${m.metrics.n}／${m.metrics.groups}<small>${m.metrics.validation==='source'?'来源与成分分组':'成分分组'}</small></td><td>${number(m.metrics.mae)}</td><td>${number(m.metrics.errorP90)}</td><td>${number(m.metrics.r2)}</td><td>${(m.featureImportance||[]).slice(0,3).map(row=>esc(row.name)).join('、')||'—'}</td><td>${m.active?'已启用':m.usable?'历史版本':'未优于基线'}${m.revision!==workspace.revision?'<small class="prediction-warning">数据已变更，建议重训</small>':''}</td><td><button class="text-button" data-model-details="${esc(m.id)}">训练报告</button>${m.usable&&!m.active?`<button class="text-button" data-activate-model="${esc(m.id)}">启用此版本</button>`:''}<button class="text-button" data-remove-model="${esc(m.id)}">移除…</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="prediction-empty"><p>训练完成后，这里会保留误差、适用范围、主要输入和模型版本。</p></div>'}</div>${modelReport(workspace.models.find(m=>m.id===reportId))}`;}
 function propertiesHTML(){return`<div class="prediction-card"><h3>扩展预测目标与输入描述符</h3><p class="prediction-help">可建立任意数值回归目标，并增加结构、工艺、计算或测试描述符。目标的必填描述符会在训练和预测时强制检查。</p><form id="prediction-field-form" class="prediction-grid"><label>字段用途<select name="kind"><option value="target">数值预测目标</option><option value="number">数值输入描述符</option><option value="category">分类输入描述符</option></select></label><label>名称<input name="name" required maxlength="100" placeholder="例如 形成能"></label><label>单位<input name="unit" maxlength="40" placeholder="例如 eV/atom；无量纲可留空"></label><label>目标必填描述符<select name="requiredFeature" multiple size="3">${workspace.features.map(feature=>option(feature.id,unitLabel(feature),false)).join('')}</select><small>仅新增预测目标时使用；可按 Ctrl 多选</small></label><button type="submit" class="outline-button" ${busy?'disabled':''}>新增字段</button></form></div><div class="prediction-two-col"><div class="prediction-card"><h3>数值预测目标 · ${workspace.properties.length}</h3><div class="prediction-field-list">${workspace.properties.map(p=>`<div><span>${esc(p.name)}</span><small>${esc(p.unit||'无量纲')}${p.requiredFeatures?.length?' · 必填 '+p.requiredFeatures.map(id=>workspace.features.find(f=>f.id===id)?.name||id).join('、'):''}</small></div>`).join('')}</div><p class="prediction-help">同名但单位、测试方法或物理含义不同的目标，应创建为独立字段。</p></div><div class="prediction-card"><h3>输入描述符 · ${workspace.features.length}</h3><div class="prediction-field-list">${workspace.features.map(f=>`<div><span>${esc(f.name)}</span><small>${esc(f.unit|| (f.type==='category'?'分类':'无量纲'))}</small></div>`).join('')}</div></div></div>`;}
 function resetMapping(){mapping=(file.sheets[sheet].rows[headerRow-1]||[]).map(h=>suggestMapping(h,workspace.properties,workspace.features));preview=null;}
 async function runTraining(data){
  if(busy)return;await engineReady;if(!engine?.ready)throw Error(engine?.error||'机器学习引擎未就绪。');
  const datasetIds=data.getAll('dataset'),targets=data.getAll('target');if(!targets.length)throw Error('请勾选要训练的性能。');if(!datasetIds.length)throw Error('请选择训练数据集。');
  captureTraining();const token=generation,snapshot=structuredClone(workspace);busy=true;trainStatus='准备训练…';error='';render();let completed=0;
  try{for(const target of targets){if(token!==generation)return;const id=uid(),title=workspace.properties.find(p=>p.id===target)?.name;
    trainStatus=`正在训练 ${title}（${completed+1}/${targets.length}）`;
    worker={cancel:()=>ml.mlCancel(id),terminate:()=>ml.mlCancel(id)};
    const off=ml.onMLProgress(progress=>{if(progress.id===id&&token===generation){trainStatus=title+' · '+progress.message;const node=host.querySelector('#prediction-train-status');if(node)node.textContent=trainStatus;}});render();
    let model;try{model=await ml.mlRun({action:'train',id,libraryKey,workspace:snapshot,options:{...trainingSettings,target,datasetIds,form,basis,validation:data.get('validation')}});}finally{off();}
    worker=null;if(token!==generation)return;
    const next=structuredClone(workspace);if(model.usable)for(const m of next.models)if(m.target===target&&m.form===form&&m.basis===basis)m.active=false;
    next.models.push({...model,active:model.usable});await save(next);busy=true;completed++;reportId=model.id;
   }trainStatus=`已完成 ${completed} 项训练。查看下方验证结果。`;
  }finally{worker?.terminate();worker=null;if(token===generation){busy=false;render();}}
 }
 async function prediction(data){capture();const composition=parseComposition(data.get('formula'),basis),models=activeModels(),token=generation;results=[];busy=true;render();
  try{for(const m of models){try{const r=m.algorithm==='sklearn-regression-v1'?(await ml.mlRun({action:'predict',id:uid(),libraryKey,model:m,rows:[{composition,features:conditions}]}))[0]:predictProperty(m,{composition,features:conditions});if(token!==generation)return;results.push({target:m.target,...r,stale:m.revision!==workspace.revision,modelId:m.id});}catch(e){results.push({target:m.target,error:e.message});}}
  if(!results.some(r=>r.target==='deltaTx'&&r.value!==undefined)){const tg=results.find(r=>r.target==='Tg'),tx=results.find(r=>r.target==='Tx');if(tg?.value!==undefined&&tx?.value!==undefined){results=results.filter(r=>r.target!=='deltaTx');results.push({target:'deltaTx',value:tx.value-tg.value,derived:true,warnings:[...(tg.warnings||[]),...(tx.warnings||[])],stale:tg.stale||tx.stale});}}
  lastResultInput={formula:compositionKey(composition),composition,form,basis,conditions:{...conditions}};}finally{if(token===generation){busy=false;render();}}
 }
 async function batchPrediction(selected){
  const token=generation,models=activeModels();if(!models.length)throw Error('请先训练并启用模型。');
  busy=true;render();
  try{const file=await readPredictionFile(selected),table=file.sheets[0].rows,headers=table[0]||[],columns=headers.map(h=>suggestMapping(h,workspace.properties,workspace.features));
   const compositionColumn=columns.findIndex(c=>c.role==='composition');if(compositionColumn<0)throw Error('批量预测需要 composition 成分式列，描述符列使用字段 ID 或名称。');
   if(table.length>30001)throw Error('每次批量预测最多 30,000 行。');
   const records=table.slice(1).map((cells,i)=>{try{const features={};for(let j=0;j<columns.length;j++){const c=columns[j],v=cells[j];if(c.role!=='feature'||v===undefined||v==='')continue;const f=workspace.features.find(f=>f.id===c.id);features[c.id]=f.type==='number'?exactNumber(v):String(v);if(f.type==='number'&&features[c.id]===null)throw Error(f.name+'必须是确定数值。');}return{row:i+2,formula:cells[compositionColumn],composition:parseComposition(cells[compositionColumn],basis),features};}catch(e){return{row:i+2,formula:cells[compositionColumn],error:e.message};}});
   const output=[['原始行','成分','目标','单位','预测值','经验误差下限','经验误差上限','状态／提示','模型ID']];
   const valid=records.filter(r=>!r.error);
   for(const m of models){const predicted=valid.length?(m.algorithm==='sklearn-regression-v1'?await ml.mlRun({action:'predict',id:uid(),libraryKey,model:m,rows:valid}):valid.map(r=>{try{return predictProperty(m,r);}catch(e){return{error:e.message};}})):[];if(token!==generation)return;
    let cursor=0;for(const r of records){const value=r.error?{error:r.error}:predicted[cursor++];output.push([r.row,r.formula,m.property.name,m.property.unit,value.value??'',value.interval?.[0]??'',value.interval?.[1]??'',[value.error,...(value.warnings||[]),m.revision!==workspace.revision?'训练数据已变更':''].filter(Boolean).join('；'),m.id]);}
   }
   await saveText(toCSV(output),'materia-batch-predictions.csv','csv');toast('批量预测完成，已导出结果；无效行保留错误说明。');
  }finally{if(token===generation){busy=false;render();}}
 }
 host.addEventListener('submit',async event=>{event.preventDefault();if(!loaded||busy)return;try{const data=new FormData(event.target);error='';
  if(event.target.id==='prediction-form')await prediction(data);
  if(event.target.id==='prediction-field-form'){
   const name=String(data.get('name')).trim(),unit=String(data.get('unit')).trim(),kind=data.get('kind'),next=structuredClone(workspace),items=kind==='target'?next.properties:next.features;
    if(!name||items.some(f=>f.name===name))throw Error('名称为空或已存在。');items.push({id:'custom_'+uid().replaceAll('-',''),name,unit,aliases:[name],...(kind==='target'?{requiredFeatures:data.getAll('requiredFeature')}:{type:kind})});await save(next);preview=null;render();toast('字段已新增，可在导入时映射。');
  }
  if(event.target.id==='prediction-import-form'){
   draftName=String(data.get('name'));previewOptions={name:draftName,basis:data.get('basis'),form:data.get('form')};
   preview=buildDataset({...previewOptions,table:file.sheets[sheet].rows.slice(headerRow-1),mapping,features:workspace.features,properties:workspace.properties,filename:file.filename,sheetName:file.sheets[sheet].name});render();
  }
  if(event.target.id==='prediction-train-form')await runTraining(data);
 }catch(e){error=error.startsWith('未保存')?error:e.message;render();toast(e.message,true);}},{signal:listeners.signal});
 host.addEventListener('change',async event=>{const el=event.target;if(busy)return;try{
  if(el.id==='prediction-batch'&&el.files[0])await batchPrediction(el.files[0]);
  if(el.id==='prediction-upload'){const selected=el.files[0];if(!selected)return;const incoming=await readPredictionFile(selected);host.querySelector('#prediction-import-form')?.remove();file=incoming;importSettings={basis:'at',form:'',verified:false};sheet=0;headerRow=1;draftName=selected.name.replace(/\.[^.]+$/,'');resetMapping();render();}
  if(el.id==='prediction-restore'){const selected=el.files[0];if(!selected)return;if(selected.size>512*1024*1024)throw Error('工作区文件超过 512 MB。');const next=validateWorkspace(JSON.parse(await selected.text()));if(!confirm('恢复将替换当前预测工作区的数据集与模型。请先导出备份。继续恢复？'))return;await save(next);file=null;results=[];render();}
  if(el.id==='prediction-sheet'||el.id==='prediction-header'){host.querySelector('[name="verified"]').checked=false;draftName=host.querySelector('#prediction-import-form [name="name"]')?.value||draftName;if(el.id==='prediction-sheet'){sheet=Number(el.value);headerRow=1;}else headerRow=Math.max(1,Math.min(file.sheets[sheet].rows.length,Number(el.value)||1));resetMapping();render();}
  if(el.dataset.mappingRole!==undefined){host.querySelector('[name="verified"]').checked=false;const i=Number(el.dataset.mappingRole),role=el.value;mapping[i]={role,id:role==='target'?workspace.properties[0].id:role==='feature'?workspace.features[0].id:role==='element'?'Fe':''};preview=null;draftName=host.querySelector('#prediction-import-form [name="name"]')?.value||draftName;render();}
  if(el.dataset.mappingId!==undefined){host.querySelector('[name="verified"]').checked=false;mapping[Number(el.dataset.mappingId)].id=el.value;preview=null;render();}
  if(el.closest('#prediction-import-form')&&['name','form','basis','verified'].includes(el.name)){preview=null;const report=host.querySelector('.prediction-import-report');report?.remove();}
  if(el.closest('#prediction-form')){capture();if(['basis','form'].includes(el.name)){results=[];render();}}
  if(el.closest('#prediction-train-form')&&['basis','form'].includes(el.name)){form=el.closest('form').elements.form.value;basis=el.closest('form').elements.basis.value;results=[];render();}
 }catch(e){error=error.startsWith('未保存')?error:e.message;render();toast(e.message,true);}},{signal:listeners.signal});
 host.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;try{
  if(button.dataset.predictionPanel){if(busy){toast('请等待当前操作完成，或停止训练。');return;}capture();panel=button.dataset.predictionPanel;render();return;}
  const action=button.dataset.predictionAction;
  if(action==='cancel-train'){worker?.cancel();return;}
  if(busy)return;
  if(action==='retry'){error='';await ensureLoaded();}
  if(action==='add-element')host.querySelector('#prediction-element-rows').insertAdjacentHTML('beforeend',elementRow());
  if(action==='remove-element')button.closest('.prediction-element').remove();
  if(action==='apply-elements'){const c={};for(const row of host.querySelectorAll('.prediction-element')){const e=row.querySelector('select').value,n=exactNumber(row.querySelector('input').value);if(!e||n===null)throw Error('每一行都需要元素和百分比。');if(c[e]!==undefined)throw Error('同一个元素不能重复。');c[e]=n;}formula=compositionKey(validateComposition(c));host.querySelector('[name="formula"]').value=formula;}
  if(action==='close-import'){file=null;preview=null;render();}
  if(action==='confirm-import'){if(!preview)return;const next=structuredClone(workspace);next.datasets.push(preview);next.revision++;await save(next);file=null;preview=null;results=[];render();toast('实验数据已导入，可到模型训练中选择性能。');}
  if(action==='template'){const columns=['composition',...workspace.features.map(f=>f.id+(f.unit?'('+f.unit+')':'')),...workspace.properties.map(p=>p.id+(p.unit?'('+p.unit+')':'')),'DOI'];await saveText(toCSV([columns,['LiFePO4',...columns.slice(1).map(()=>'')]]),'materia-materials-ml-template.csv','csv');}
  if(action==='export-workspace')await saveText(JSON.stringify(workspace,null,2),'materia-prediction-workspace.json','json');
  if(action==='export-results')await saveText(toCSV([['成分','材料类型','成分表达','输入描述符','预测目标','预测值','经验误差下限','经验误差上限','单位','分组验证MAE','状态／提示','模型ID','数值类型'],...results.map(r=>{const p=workspace.properties.find(p=>p.id===r.target);return[lastResultInput.formula,formLabel(lastResultInput.form),basisLabel(lastResultInput.basis),JSON.stringify(lastResultInput.conditions),p.name,r.value??'',r.interval?.[0]??'',r.interval?.[1]??'',p.unit,r.mae??'',r.error||[r.stale?'数据已变更':'',...(r.warnings||[])].filter(Boolean).join('；'),r.modelId||'',r.derived?'由预测值计算':'模型预测，非实测'];})]),'materia-material-predictions.csv','csv');
  if(button.dataset.removeDataset){const d=workspace.datasets.find(d=>d.id===button.dataset.removeDataset);if(!confirm('移除数据集“'+d.name+'”？依赖此数据集的模型会停用。'))return;const next=structuredClone(workspace);next.datasets=next.datasets.filter(d=>d.id!==button.dataset.removeDataset);for(const m of next.models)if(m.datasetIds.includes(button.dataset.removeDataset))m.active=false;next.revision++;await save(next);results=[];render();}
  if(button.dataset.exportDataset){const d=workspace.datasets.find(d=>d.id===button.dataset.exportDataset),cols=[...workspace.features.map(f=>f.id),...workspace.properties.map(p=>p.id)];await saveText(toCSV([['composition',...cols,'DOI'],...d.rows.map(r=>[compositionKey(r.composition),...workspace.features.map(f=>r.features[f.id]??''),...workspace.properties.map(p=>r.targets[p.id]??r.original[p.id]??''),r.source])]),'materia-dataset.csv','csv');}
  if(action==='close-report'){reportId=null;render();}
  if(button.dataset.activateModel){const next=structuredClone(workspace),chosen=next.models.find(m=>m.id===button.dataset.activateModel);if(!chosen?.usable)throw Error('该模型未通过基线对照。');if(chosen.datasetIds.some(id=>!next.datasets.some(d=>d.id===id)))throw Error('模型依赖的数据集已移除，请恢复数据集或重新训练。');for(const m of next.models)if(m.target===chosen.target&&m.form===chosen.form&&m.basis===chosen.basis)m.active=m.id===chosen.id;await save(next);results=[];render();}
  if(button.dataset.removeModel){if(!confirm('移除此模型及其训练报告？原始数据集保留，请先导出需要的模型备份。'))return;const next=structuredClone(workspace);next.models=next.models.filter(m=>m.id!==button.dataset.removeModel);await save(next);results=[];render();}
  if(button.dataset.modelDetails){reportId=button.dataset.modelDetails;render();host.querySelector('.prediction-model-report')?.scrollIntoView({behavior:'smooth',block:'start'});}
  if(button.dataset.exportReport){const m=workspace.models.find(m=>m.id===button.dataset.exportReport);const {artifact,forest,...report}=m;await saveText(JSON.stringify(report,null,2),'materia-training-report.json','json');}
  if(button.dataset.exportValidation){const m=workspace.models.find(m=>m.id===button.dataset.exportValidation);await saveText(toCSV([['实测值','折外预测值','残差','性能','单位','验证方式','折','分组','数据集','行ID','来源'],...m.validationPoints.map(p=>[p.actual,p.predicted,p.actual-p.predicted,m.property.name,m.property.unit,m.metrics.validation,p.fold??'',p.group??'',p.datasetId??'',p.rowId??'',p.source??''])]),'materia-model-validation.csv','csv');}
 }catch(e){error=error.startsWith('未保存')?error:e.message;render();toast(e.message,true);}},{signal:listeners.signal});
 return{
  show(){if(!isReady())return;ensureLoaded();if(loaded&&!host.children.length)render();status();},
  async flush(){if(busy)throw Error('请等待性能模型训练完成，或先停止训练。');await queue;if(error.startsWith('未保存'))throw Error(error);},
  reset(){generation++;worker?.cancel();worker?.terminate();worker=null;loaded=false;loading=null;workspace=freshWorkspace();file=null;preview=null;results=[];conditions={};formula='';busy=false;error='';trainStatus='';host.replaceChildren();},
  dispose(){generation++;listeners.abort();worker?.cancel();worker?.terminate();worker=null;host.replaceChildren();},
 };
}
